class RecordingNotifier(Notifier):
    """Captures notifications instead of POSTing them."""

    def __init__(self):
        super().__init__(sink_url="memory://")
        self.sent: list[dict] = []

    def send(self, notification: dict) -> None:
        self.sent.append(notification)


